1import { useState } from "react";
2
3function JournalForm({onAddEntry}) {
4  const [title, setTitle] = useState("");
5  const [content, setContent] = useState("");
6
7  function handleSubmit(e) {
8    e.preventDefault();
9
10    if (title.trim() === "" || content.trim() === "") return;
11
12    onAddEntry(title, content);
13
14    setTitle("");
15    setContent("");
16  }
17
18  return (
19    <section className="card">
20      <div className="form-header">
21        <h2 className="form-title">New Entry</h2>
22      </div>
23      <form onSubmit={handleSubmit}>
24        <div className="form-group">
25          <label htmlFor="title">Title</label>
26          <input
27            id="title"
28            type="text"
29            placeholder="Entry title"
30            className="input-field"
31            value={title}
32            onChange={(e) => setTitle(e.target.value)}
33          />
34        </div>
35        <div className="form-group">
36          <label htmlFor="content">Content</label>
37          <textarea
38            id="content"
39            placeholder="What's on your mind?"
40            className="textarea-field"
41            rows={4}
42            value={content}
43            onChange={(e) => setContent(e.target.value)}
44          />
45        </div>
46        <div className="btn-group">
47          <button type="button" className="btn btn-secondary">Clear</button>
48          <button type="submit" className="btn btn-primary">Add Entry</button>
49        </div>
50      </form>
51    </section>
52  );
53}
54
55export default JournalForm;

